"""Root-authored full text and profile corrections for seven audited teams."""
import copy,json
from pathlib import Path
ROOT=Path(__file__).parent
def read(n):return json.loads((ROOT/n).read_text(encoding='utf8'))
a=read('inventory/critic-full-team-audit-b.json');q=a['findings'];c=read('inventory/current-rule-base-cards.json');out=[]
sources={s['team']:s for s in a['sources']}
def p(n):
 x=q[n];id=x['exactID'];v=c[id];s=sources[x['team']]
 t={'id':id,'expectedTitle':v['titleEnglish'],'team':x['team'],'source':{'officialPdf':s['officialPdf'],'date':s['officialCatalogDate'],'wahapedia':s['wahaPage'],'checkedOn':'2026-10-05','evidence':x['evidence']}};out.append(t);return t
def b(n,heading):return next(x for x in c[q[n]['exactID']].get('blocks',[]) if x.get('headingEnglish')==heading)
def text(n,heading,ru,en=None,append=False,ruHeading=None):
 t=p(n);u={'heading':heading,'russian':ru,'english':en or q[n]['currentfullrule'],'proseTitles':[heading.split(' ·')[0].split(' (')[0].split(':')[0]]}
 if append:u.update(append=True,headingRussian=ruHeading)
 t['blocks']=[u];return t
def replace(n,heading,ruOld,ruNew,enOld,enNew):
 v=b(n,heading);assert ruOld in v['russian'],(n,ruOld);assert enOld in v['english'],(n,enOld)
 return text(n,heading,v['russian'].replace(ruOld,ruNew),v['english'].replace(enOld,enNew))
def extend(n,heading,ru,en):
 v=b(n,heading);return text(n,heading,v['russian']+'\n'+ru,v['english']+' '+en)

text(0,'Harrowing Whispers','Когда противник собирается активировать вражеского оперативника в пределах 6 дюймов от этого оперативника, можно бросить один D6. Нельзя делать этот бросок, если в этом раунде вы уже прерывали активацию выбранного врага этим правилом или правилом «Зловещий прицел» (Haunting Focus) оперативника DIRGEMAW. Если результат D6 выше APL выбранного врага, противник не может активировать его в эту активацию. Если нет других врагов, которых можно активировать, правило не действует.')
text(1,'Haunting Focus: STRATEGIC GAMBIT','Выберите одного вражеского оперативника: до шага готовности (Ready) следующей фазы стратегии он получает ваш жетон зловещего прицела (Haunting Focus). Когда противник в следующий раз собирается активировать врага с этим жетоном, если этот оперативник готов, можно сначала активировать его. Нельзя делать это, если в этом раунде вы уже бросали кубик для предотвращения активации выбранного врага правилом «Мучительные шёпоты» (Harrowing Whispers) оперативника NIGHTFIEND.\nВ эту активацию этот оперативник должен сразиться с выбранным врагом или выстрелить по нему; до этого он не может сражаться или стрелять по другим врагам. Если выполнить это невозможно, активация отменяется. После его активации противник активирует выбранного врага, если возможно, либо другого врага, если выбранного активировать нельзя.',en='Select one enemy operative. Until the Ready step of the next Strategy phase, it gains your Haunting Focus token. '+q[1]['currentfullrule'])
text(2,'Pareidolic Projection (1AP)','Выберите одного врага, который является допустимой целью для этого оперативника или находится в тени (WITHIN SHADOW). До начала следующей активации этого оперативника, его выведения из строя или повторного выполнения им этого действия — что наступит раньше — ухудшите HIT оружия выбранного врага на 1 и уменьшите его MOVE на 2 дюйма. Эффект не суммируется с ранением.\nЭто действие нельзя выполнять в дистанции контроля врага, если только выбранный враг не является единственным врагом в дистанции контроля этого оперативника.',en=q[2]['currentfullrule'].replace(' The APL clause is deleted.',''))
for n in [3,12]:extend(n,'Rule','После результата 4+ это правило нельзя применять повторно в том же раунде.','If any result is a 4+, you cannot use this rule again during this turning point.')
